package vn.boardinghub.modules.room;import jakarta.validation.constraints.*;import java.math.BigDecimal;public final class RoomDtos{private RoomDtos(){}public record Request(@NotNull Long propertyId,@NotBlank @Size(max=30)String code,@NotNull @PositiveOrZero BigDecimal monthlyRent,@Min(1)@Max(30)int capacity,@Size(max=500)String description){}public record Response(Long id,Long propertyId,String propertyName,String code,BigDecimal monthlyRent,int capacity,RoomStatus status,String description){}static Response from(Room r){return new Response(r.getId(),r.getProperty().getId(),r.getProperty().getName(),r.getCode(),r.getMonthlyRent(),r.getCapacity(),r.getStatus(),r.getDescription());}}
